<script setup>
import {ref,computed,watch,onUnmounted,nextTick} from 'vue';import axios from 'axios';import CoveragePicker from './CoveragePicker.vue';import BlueprintEditor from './BlueprintEditor.vue';import {message} from '../art';
const props=defineProps({form:Object,catalog:Object,bento:Boolean,busy:Boolean,submitLabel:{default:'Start round'}});const emit=defineEmits(['start']);
const builder=ref(null),step=ref(1),available=ref(null),checking=ref(false),error=ref(''),allocationMode=ref(props.form.blueprint?.length?'topics':Object.keys(props.form.allocation||{}).length?'custom':'balanced');
watch(allocationMode,m=>{if(m==='topics'){if(!props.form.blueprint?.length)props.form.blueprint=[{subject:props.form.subjects[0],topic:'',difficulty:'All',count:Number(props.form.count)}]}else props.form.blueprint=[]});
let timer,seq=0,controller;
const scopeOk=computed(()=>props.form.subjects.length>0&&(props.form.topic_scope!=='custom'||props.form.topics.length>0));
const blueprint=computed(()=>Object.fromEntries(props.form.subjects.map((s,i)=>[s,Math.floor(Number(props.form.count)/props.form.subjects.length)+(i<Number(props.form.count)%props.form.subjects.length?1:0)])));
watch(()=>[props.form.count,props.form.subjects.slice(),allocationMode.value],()=>{if(props.bento&&allocationMode.value==='balanced')props.form.allocation={...blueprint.value};else if(props.bento)props.form.allocation=Object.fromEntries(props.form.subjects.map(s=>[s,props.form.allocation[s]??0]))},{immediate:true,deep:true});
watch(()=>JSON.stringify(props.form.data?props.form.data():props.form),()=>{
 clearTimeout(timer);controller?.abort();const request=++seq;available.value=null;error.value='';
 if(!scopeOk.value){checking.value=false;return}
 checking.value=true;timer=setTimeout(async()=>{controller=new AbortController();try{const r=await axios.post('/study/available',props.form.data?props.form.data():props.form,{signal:controller.signal});if(request===seq)available.value=r.data}catch(e){if(request===seq&&!axios.isCancel(e))error.value=message(e)}finally{if(request===seq)checking.value=false}},250);
},{immediate:true});
onUnmounted(()=>{clearTimeout(timer);controller?.abort();seq++});
const quotaProblem=computed(()=>allocationMode.value==='topics'&&!props.form.blueprint?.length?'Add at least one quota row.':'');
const canStart=computed(()=>scopeOk.value&&!quotaProblem.value&&!checking.value&&!error.value&&available.value&&!available.value.problem);
watch(step,()=>nextTick(()=>{builder.value?.querySelectorAll('[data-step-heading]')[step.value-1]?.focus({preventScroll:true});builder.value?.scrollIntoView({block:'start'})}));
function next(){if(step.value<3)step.value++}
</script>
<template><div ref="builder" class="round-builder"><div class="builder-steps" aria-label="Round setup"><button v-for="[n,label] in [[1,'Coverage'],[2,'Round settings'],[3,'Review']]" :key="n" type="button" :disabled="n>1&&!scopeOk" :class="{selected:step===n}" :aria-current="step===n?'step':undefined" @click="step=n"><strong>{{n}}</strong>{{label}}</button></div>
<div class="builder-layout"><div><div v-show="step===1"><h2 data-step-heading tabindex="-1">Choose coverage</h2><CoveragePicker :form="form" :catalog="catalog" :counts="available?.topics"/></div>
<div v-show="step===2" class="builder-options"><h2 data-step-heading tabindex="-1">Round settings</h2><fieldset><legend>Number of questions</legend><div class="segmented"><button v-for="n in [10,20,40,100]" :key="n" type="button" :class="{selected:form.count===n}" @click="form.count=n">{{n}}</button></div><label class="count-custom">Custom count<input v-model.number="form.count" type="number" min="1" max="10000"></label></fieldset>
<fieldset><legend>Difficulty</legend><div class="segmented"><button v-for="d in ['All','Easy','Average','Difficult']" :key="d" type="button" :class="{selected:form.difficulty===d}" @click="form.difficulty=d">{{d==='All'?'Mixed':d}}</button></div></fieldset>
<fieldset><legend>Question pool</legend><div class="segmented"><button v-for="[v,l] in [['all','All'],['new','Unseen'],['missed','Missed'],['bookmarks','Saved']]" :key="v" type="button" :class="{selected:form.pool===v}" @click="form.pool=v">{{l}}</button></div></fieldset>
<fieldset v-if="form.mode==='exam'&&!bento"><legend>Time limit</legend><div class="segmented"><button v-for="n in [15,30,60,120]" :key="n" type="button" :class="{selected:form.minutes===n}" @click="form.minutes=n">{{n}} min</button></div><label class="count-custom">Custom minutes<input v-model.number="form.minutes" type="number" min="1" max="360"></label></fieldset>
<fieldset v-if="bento"><legend>Exam blueprint</legend><div class="segmented"><button type="button" :class="{selected:allocationMode==='balanced'}" @click="allocationMode='balanced'">Balanced</button><button type="button" :class="{selected:allocationMode==='custom'}" @click="allocationMode='custom'">Custom subject counts</button><button type="button" :class="{selected:allocationMode==='topics'}" @click="allocationMode='topics'">Topic + difficulty quotas</button></div><BlueprintEditor v-if="allocationMode==='topics'" :form="form" :catalog="catalog"/>
<div v-if="allocationMode!=='topics'" class="blueprint"><div v-for="s in form.subjects" :key="s"><span>{{s}}</span><input v-if="allocationMode==='custom'" v-model.number="form.allocation[s]" type="number" min="0" :aria-label="s+' question count'"><strong v-else>{{form.allocation[s]}}</strong></div></div><small v-if="allocationMode==='custom'">Counts must total {{form.count}} questions.</small></fieldset>
</div>
<div v-show="step===3"><h2 data-step-heading tabindex="-1">{{bento?'Review your recipe':'Review round'}}</h2><ul class="summary-list"><li>{{form.count}} questions · {{form.difficulty==='All'?'mixed difficulty':form.difficulty}}</li><template v-if="form.blueprint?.length"><li v-for="(row,i) in form.blueprint" :key="i">{{row.count}} × {{row.subject}} · {{row.topic||'All selected topics'}} · {{row.difficulty==='All'?'Mixed difficulty':row.difficulty}}</li></template><template v-else><li>{{form.subjects.join(', ')}}</li><li>{{form.topics.length?form.topics.length+' selected topics':'All topics'}}</li></template><li>{{{all:'All questions',new:'Unseen questions',missed:'Previously missed',bookmarks:'Saved questions'}[form.pool]}}</li><li v-if="form.mode==='exam'&&!bento">{{form.minutes}} minutes · answers after submission</li><li v-else-if="!bento">Immediate answer feedback</li></ul><p v-if="bento">Next, inspect the actual questions and replace any before saving.</p><slot name="review"/></div>
<div class="builder-actions"><button v-if="step>1" type="button" @click="step--">Back</button><span v-else></span><button v-if="step<3" type="button" class="primary" :disabled="!scopeOk" @click="next">Continue</button><button v-else type="button" class="primary" :disabled="!canStart||busy" @click="emit('start')">{{busy?'Preparing…':submitLabel}}</button></div></div>
<aside class="builder-summary" aria-live="polite"><p class="eyebrow">On your menu</p><strong class="total">{{checking?'…':(available?.available??'—')}}</strong><small>distinct questions available</small><p>{{form.count}} requested</p><p v-if="quotaProblem||available?.problem||error" class="error">{{quotaProblem||available?.problem||error}}</p><p v-else-if="checking">Checking your selection…</p><div v-if="bento&&allocationMode!=='topics'" class="blueprint"><div v-for="s in form.subjects" :key="s"><span>{{s}}</span><strong>{{form.allocation?.[s]||0}}</strong></div></div></aside></div></div></template>
